import {useMemo, type FC} from 'react'
import {
  SecurityProductsFilterBar,
  parseAsUser,
  serializeLogin,
  filterDefinition,
  timePeriodFilterDefinition,
  repositoryFilterDefinition,
  staticOrganizationFilterDefinition,
  type FilterDefinition,
} from '@github-ui/repos-rules/SecurityProductsFilterBar'
import type {SourceType} from '@github-ui/repos-rules/types/rules-types'
import {ApproverFilterProvider} from './providers/approver'
import {RequesterFilterProvider} from './providers/requester'
import {RequestStatusFilterProvider} from './providers/request-status'
import {SortFilterProvider} from './providers/sort'
import type {DelegatedBypassFilter} from '../delegated-bypass-types'
import {requestsIndexPath} from '../helpers/requests-filter'
import {useBypassActors} from '../hooks/use-bypass-actors'
import {useRelativeNavigation} from '../hooks/use-relative-navigation'

type BypassRequestsFilterBar2Props = {
  filter: DelegatedBypassFilter
  sourceType: SourceType
  organizations?: string[]
  sortingEnabled?: boolean
}

export const BypassRequestsFilterBar2: FC<BypassRequestsFilterBar2Props> = ({
  filter,
  sourceType,
  organizations,
  sortingEnabled,
}) => {
  const requestersState = useBypassActors('Requester')
  const approversState = useBypassActors('Approver')
  const {resolvePath} = useRelativeNavigation()
  const repoSuggestionsUrl = resolvePath('repo_suggestions')

  const filterDefinitions = useMemo<Array<FilterDefinition<DelegatedBypassFilter>>>(
    () => [
      timePeriodFilterDefinition<DelegatedBypassFilter>(),
      ...(sourceType === 'organization' ? [repositoryFilterDefinition<DelegatedBypassFilter>(repoSuggestionsUrl)] : []),
      ...(sourceType === 'enterprise' && organizations?.length
        ? [staticOrganizationFilterDefinition<DelegatedBypassFilter>(organizations)]
        : []),
      filterDefinition<DelegatedBypassFilter>({
        config: {
          filterKey: 'requester',
          queryKey: 'requester',
          parse: parseAsUser,
          serialize: v => serializeLogin(v as {login: string}),
        },
        provider: new RequesterFilterProvider(requestersState.users),
      }),
      filterDefinition<DelegatedBypassFilter>({
        config: {
          filterKey: 'approver',
          queryKey: 'approver',
          parse: parseAsUser,
          serialize: v => serializeLogin(v as {login: string}),
        },
        provider: new ApproverFilterProvider(approversState.users),
      }),
      filterDefinition<DelegatedBypassFilter>({
        config: {filterKey: 'requestStatus', queryKey: 'request-status'},
        provider: new RequestStatusFilterProvider(),
      }),
      ...(sortingEnabled
        ? [
            filterDefinition<DelegatedBypassFilter>({
              config: {filterKey: 'sort', queryKey: 'sort'},
              provider: new SortFilterProvider(),
            }),
          ]
        : []),
    ],
    [sourceType, organizations, repoSuggestionsUrl, requestersState.users, approversState.users, sortingEnabled],
  )

  return (
    <div className="tmp-mb-3">
      <SecurityProductsFilterBar<DelegatedBypassFilter>
        id="bypass-requests-filter"
        label="Filter bypass requests"
        filter={filter}
        filterDefinitions={filterDefinitions}
        getIndexPath={requestsIndexPath}
      />
    </div>
  )
}
