import {SelectFilterProvider} from '@github-ui/filter-core/providers'
import {CheckCircleIcon} from '@primer/octicons-react'
import {orderedStatuses, requestStatuses} from '../../helpers/constants'
import {DEFAULT_FILTER_PRIORITY} from '@github-ui/filter-core'
import {singleValueFilterTypes} from '@github-ui/repos-rules/shared-filter-types'

export class RequestStatusFilterProvider extends SelectFilterProvider {
  constructor() {
    super(
      {
        displayName: 'Request status',
        key: 'request-status',
        priority: DEFAULT_FILTER_PRIORITY,
        icon: CheckCircleIcon,
        description: 'Specify the request status',
      },
      orderedStatuses.map((status, index) => ({
        value: status,
        displayName: requestStatuses[status],
        priority: index + 1,
      })),
      {
        filterTypes: singleValueFilterTypes,
        renderValueVisual: () => null,
      },
    )
  }
}
