import {useMemo} from 'react'
import {Pagination, Link} from '@primer/react'
import {Subhead} from '../components/Subhead'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {BypassRequestsRoutePayload, ExemptionRequest} from '../delegated-bypass-types'
import {DelegatedBypassRow} from '../components/DelegatedBypassRow'
import {useRelativeNavigation} from '../hooks/use-relative-navigation'
import {BypassRequestsFilterBar} from '../components/BypassRequestsFilterBar'
import {BypassRequestsFilterBar2} from '../components/BypassRequestsFilterBar2'
import {requestsIndexPath} from '../helpers/requests-filter'
import {BypassRequestsBlank} from '../components/BypassRequestsBlank'
import {componentRegistry} from '../components/RequestForm/index'
import {useRequestTypeContext} from '../contexts/RequestTypeContext'
import {useIsStafftools} from '../hooks/use-is-stafftools'

const RULES_REQUEST_TYPES: readonly string[] = [
  'multiple_bypass_types',
  'push_ruleset_bypass',
  'repository_policy_ruleset_bypass',
]
const SECRET_SCANNING_REQUEST_TYPES: readonly string[] = ['secret_scanning', 'secret_scanning_closure']
const CODE_SCANNING_REQUEST_TYPES: readonly string[] = ['code_scanning_alert_dismissal']
const DEPENDABOT_REQUEST_TYPES: readonly string[] = ['dependabot_alert_dismissal']
const LICENSE_COMPLIANCE_REQUEST_TYPES: readonly string[] = ['license_compliance_dismissal']

export function BypassRequestsPage() {
  return <BypassRequestsComponent />
}

function BypassRequestsComponent() {
  const {unauthorizedUser} = useRoutePayload<BypassRequestsRoutePayload>()
  const requestType = useRequestTypeContext()

  const {bypassRequestListHeader} = componentRegistry({
    requestType,
  })

  return (
    <>
      <Subhead heading={bypassRequestListHeader} />
      {!unauthorizedUser ? (
        <BypassRequestsComponentBody />
      ) : (
        <div className="border">
          <BypassRequestsBlank requestType={requestType} unauthorizedUser />
        </div>
      )}
    </>
  )
}

function BypassRequestsComponentBody() {
  const {exemptionRequests, filter, sourceType, organizations, hasMoreRequests, baseExemptionUrl} =
    useRoutePayload<BypassRequestsRoutePayload>()
  const {navigate} = useRelativeNavigation()
  const requestType = useRequestTypeContext()

  const {bypassRequestListSubheaderFn} = componentRegistry({
    requestType,
  })
  const isStafftools = useIsStafftools()

  const getBaseExemptionUrl = (exemptionRequest: ExemptionRequest) => {
    if (sourceType === 'repository') {
      return baseExemptionUrl
    }
    return isStafftools
      ? `/stafftools/repositories${exemptionRequest.repoExemptionsBaseUrl}`
      : exemptionRequest.repoExemptionsBaseUrl
  }

  const bypassRequestListSubheaderText = bypassRequestListSubheaderFn({sourceType})

  let {page} = filter
  page = page || 1
  const pageCount = hasMoreRequests ? page + 1 : page

  const sortingEnabled = SECRET_SCANNING_REQUEST_TYPES.includes(requestType)

  // Strip `sort` from filter when sorting is not enabled for this request type.
  // Without this, a `sort` value smuggled in via URL or server payload would persist through
  // pagination and other navigations that reuse `filter`, creating hidden state.
  const effectiveFilter = useMemo(() => {
    if (sortingEnabled || !filter.sort) return filter
    const {sort: _sort, ...rest} = filter
    return rest
  }, [filter, sortingEnabled])

  const useFilterBar2 = useMemo(() => {
    const isRulesFilterBarEnabled = RULES_REQUEST_TYPES.includes(requestType)
    const isSecretScanningFilterBarEnabled = SECRET_SCANNING_REQUEST_TYPES.includes(requestType)
    const isCodeScanningFilterBarEnabled = CODE_SCANNING_REQUEST_TYPES.includes(requestType)
    const isDependabotFilterBarEnabled = DEPENDABOT_REQUEST_TYPES.includes(requestType)
    const isLicenseComplianceFilterBarEnabled = LICENSE_COMPLIANCE_REQUEST_TYPES.includes(requestType)

    return (
      isRulesFilterBarEnabled ||
      isSecretScanningFilterBarEnabled ||
      isCodeScanningFilterBarEnabled ||
      isDependabotFilterBarEnabled ||
      isLicenseComplianceFilterBarEnabled
    )
  }, [requestType])

  return (
    <>
      <div className="mb-2">
        <span className="text-normal color-fg-muted">{bypassRequestListSubheaderText}</span>{' '}
        {requestType === 'secret_scanning' && (
          <>
            <Link href="https://docs.github.com/en/enterprise-cloud@latest/code-security/secret-scanning/using-advanced-secret-scanning-and-push-protection-features/delegated-bypass-for-push-protection/about-delegated-bypass-for-push-protection">
              Learn more about delegated bypass
            </Link>
            .
          </>
        )}
      </div>
      {useFilterBar2 ? (
        <BypassRequestsFilterBar2
          filter={effectiveFilter}
          sourceType={sourceType}
          organizations={organizations}
          sortingEnabled={sortingEnabled}
        />
      ) : (
        <BypassRequestsFilterBar filter={effectiveFilter} sourceType={sourceType} organizations={organizations} />
      )}
      {exemptionRequests.length > 0 ? (
        <ol className="d-flex flex-column rounded-2 overflow-hidden color-bg-default border color-border-default color-fg-default position-relative ml-0">
          {exemptionRequests.map(exemptionRequest => (
            <DelegatedBypassRow
              key={exemptionRequest.id}
              exemptionRequest={exemptionRequest}
              baseExemptionUrl={getBaseExemptionUrl(exemptionRequest)}
              sourceType={sourceType}
            />
          ))}
        </ol>
      ) : (
        <div className="d-flex flex-column rounded-2 overflow-hidden color-bg-default border color-border-default mt-2">
          <BypassRequestsBlank requestType={requestType} />
        </div>
      )}
      {(page !== 1 || pageCount !== 1) && (
        <Pagination
          pageCount={pageCount}
          currentPage={page}
          onPageChange={(e, newPage) => {
            e.preventDefault()
            if (page !== newPage) {
              navigate('.', requestsIndexPath({filter: {...effectiveFilter, page: newPage}}), true)
            }
          }}
          showPages={false}
        />
      )}
    </>
  )
}
